  const line = feedLine(e);
  return line ? { ...s, feed: [...s.feed, { seq: e.seq, ts: e.ts, agent: e.agent, ...line }].slice(-FEED_MAX) } : s;
}

function apply(prev: UiState, e: AuditEvent): UiState {
  const s: UiState = { ...prev, lastSeq: e.seq, lastTs: e.ts };

